// =====================================================================================================
// FILE: Maroos.Web/Components/Account/IdentityComponentsEndpointRouteBuilderExtensions.cs
// ORIGIN: generated by the Blazor Identity template; Maroos uses it unchanged.
// PURPOSE: The account actions that can't be Blazor pages, because they must answer a plain HTTP POST:
//   * /Account/PerformExternalLogin  start "Log in with GitHub" (send the browser to GitHub)
//   * /Account/Logout                sign out, then go back to the page you were on
//   * /Account/PasskeyCreationOptions and /Account/PasskeyRequestOptions  the data a browser needs
//                                    to create or use a passkey (called from PasskeySubmit.razor.js)
//   * /Account/Manage/LinkExternalLogin     connect GitHub to an existing account
//   * /Account/Manage/DownloadPersonalData  a JSON file of the user's personal data (privacy law)
// Program.cs calls MapAdditionalIdentityEndpoints() once at startup.
// WHY POST: signing in or out changes state, so it must not be a link another site could trigger with a GET.
// =====================================================================================================

using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Http.Extensions;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Primitives;
using Maroos.Web.Components.Account.Pages;
using Maroos.Web.Components.Account.Pages.Manage;
using Maroos.Web.Data;

namespace Microsoft.AspNetCore.Routing;

// An "extension method" class: `this IEndpointRouteBuilder endpoints` lets Program.cs write app.MapAdditionalIdentityEndpoints().
internal static class IdentityComponentsEndpointRouteBuilderExtensions
{
    // These endpoints are required by the Identity Razor components defined in the /Components/Account/Pages directory of this project.
    public static IEndpointConventionBuilder MapAdditionalIdentityEndpoints(this IEndpointRouteBuilder endpoints)
    {
        ArgumentNullException.ThrowIfNull(endpoints);

        // A route group: every endpoint below starts with /Account.
        var accountGroup = endpoints.MapGroup("/Account");

        // External login (GitHub). Step 1: build the address GitHub should send the user back to
        // (/Account/ExternalLogin?Action=LoginCallback&ReturnUrl=...). Step 2: a "Challenge" result redirects to GitHub.
        // [FromForm] values come from the posted form; [FromServices] ones from dependency injection.
        accountGroup.MapPost("/PerformExternalLogin", (
            HttpContext context,
            [FromServices] SignInManager<ApplicationUser> signInManager,
            [FromForm] string provider,
            [FromForm] string returnUrl) =>
        {
            IEnumerable<KeyValuePair<string, StringValues>> query = [
                new("ReturnUrl", returnUrl),
                new("Action", ExternalLogin.LoginCallbackAction)];

            var redirectUrl = UriHelper.BuildRelative(
                context.Request.PathBase,
                "/Account/ExternalLogin",
                QueryString.Create(query));

            var properties = signInManager.ConfigureExternalAuthenticationProperties(provider, redirectUrl);
            return TypedResults.Challenge(properties, [provider]);
        });

        // Log out: delete the login cookie, then return to the page the user was on. LocalRedirect refuses
        // addresses on other sites, so a crafted returnUrl can't bounce people somewhere malicious.
        accountGroup.MapPost("/Logout", async (
            ClaimsPrincipal user,
            [FromServices] SignInManager<ApplicationUser> signInManager,
            [FromForm] string returnUrl) =>
        {
            await signInManager.SignOutAsync();
            return TypedResults.LocalRedirect($"~/{returnUrl}");
        });

        // Passkey registration, step 1 of 2: the browser asks for "creation options" (a challenge plus the
        // user's id and name). The antiforgery check proves the request came from one of our own pages.
        accountGroup.MapPost("/PasskeyCreationOptions", async (
            HttpContext context,
            [FromServices] UserManager<ApplicationUser> userManager,
            [FromServices] SignInManager<ApplicationUser> signInManager,
            [FromServices] IAntiforgery antiforgery) =>
        {
            await antiforgery.ValidateRequestAsync(context);

            var user = await userManager.GetUserAsync(context.User);
            if (user is null)
            {
                return Results.NotFound($"Unable to load user with ID '{userManager.GetUserId(context.User)}'.");
            }

            var userId = await userManager.GetUserIdAsync(user);
            var userName = await userManager.GetUserNameAsync(user) ?? "User";
            var optionsJson = await signInManager.MakePasskeyCreationOptionsAsync(new()
            {
                Id = userId,
                Name = userName,
                DisplayName = userName
            });
            return TypedResults.Content(optionsJson, contentType: "application/json");
        });

        // Passkey sign-in, step 1 of 2: the options for using an existing passkey. The user name is optional:
        // without it, the browser offers any passkey it has for this site.
        accountGroup.MapPost("/PasskeyRequestOptions", async (
            HttpContext context,
            [FromServices] UserManager<ApplicationUser> userManager,
            [FromServices] SignInManager<ApplicationUser> signInManager,
            [FromServices] IAntiforgery antiforgery,
            [FromQuery] string? username) =>
        {
            await antiforgery.ValidateRequestAsync(context);

            var user = string.IsNullOrEmpty(username) ? null : await userManager.FindByNameAsync(username);
            var optionsJson = await signInManager.MakePasskeyRequestOptionsAsync(user);
            return TypedResults.Content(optionsJson, contentType: "application/json");
        });

        // /Account/Manage/...: RequireAuthorization means only signed-in users can call these.
        var manageGroup = accountGroup.MapGroup("/Manage").RequireAuthorization();

        // Link GitHub to the signed-in account: like PerformExternalLogin, but the callback goes to the
        // Manage/ExternalLogins page and carries the current user's id so the login is added to *this* account.
        manageGroup.MapPost("/LinkExternalLogin", async (
            HttpContext context,
            [FromServices] SignInManager<ApplicationUser> signInManager,
            [FromForm] string provider) =>
        {
            // Clear the existing external cookie to ensure a clean login process
            await context.SignOutAsync(IdentityConstants.ExternalScheme);

            var redirectUrl = UriHelper.BuildRelative(
                context.Request.PathBase,
                "/Account/Manage/ExternalLogins",
                QueryString.Create("Action", ExternalLogins.LinkLoginCallbackAction));

            var properties = signInManager.ConfigureExternalAuthenticationProperties(provider, redirectUrl, signInManager.UserManager.GetUserId(context.User));
            return TypedResults.Challenge(properties, [provider]);
        });

        // A logger for the download below (it records who asked for their data, never the data itself).
        var loggerFactory = endpoints.ServiceProvider.GetRequiredService<ILoggerFactory>();
        var downloadLogger = loggerFactory.CreateLogger("DownloadPersonalData");

        // Download my data. Step 1: load the signed-in user. Step 2: collect every property marked [PersonalData],
        // the external logins and the authenticator key. Step 3: send it as a PersonalData.json download.
        manageGroup.MapPost("/DownloadPersonalData", async (
            HttpContext context,
            [FromServices] UserManager<ApplicationUser> userManager,
            [FromServices] AuthenticationStateProvider authenticationStateProvider) =>
        {
            var user = await userManager.GetUserAsync(context.User);
            if (user is null)
            {
                return Results.NotFound($"Unable to load user with ID '{userManager.GetUserId(context.User)}'.");
            }

            var userId = await userManager.GetUserIdAsync(user);
            downloadLogger.LogInformation("User with ID '{UserId}' asked for their personal data.", userId);

            // Only include personal data for download
            var personalData = new Dictionary<string, string>();
            var personalDataProps = typeof(ApplicationUser).GetProperties().Where(
                prop => Attribute.IsDefined(prop, typeof(PersonalDataAttribute)));
            foreach (var p in personalDataProps)
            {
                personalData.Add(p.Name, p.GetValue(user)?.ToString() ?? "null");
            }

            var logins = await userManager.GetLoginsAsync(user);
            foreach (var l in logins)
            {
                personalData.Add($"{l.LoginProvider} external login provider key", l.ProviderKey);
            }

            personalData.Add("Authenticator Key", (await userManager.GetAuthenticatorKeyAsync(user))!);
            var fileBytes = JsonSerializer.SerializeToUtf8Bytes(personalData);

            context.Response.Headers.TryAdd("Content-Disposition", "attachment; filename=PersonalData.json");
            return TypedResults.File(fileBytes, contentType: "application/json", fileDownloadName: "PersonalData.json");
        });

        // Returned so Program.cs could add more rules to the whole /Account group.
        return accountGroup;
    }
}
